class Form_F_MultiMeshFunctionSpace_0 : public dolfin::MultiMeshFunctionSpace {
  public:
    // Constructor for multimesh function space
    Form_F_MultiMeshFunctionSpace_0(std::shared_ptr<const dolfin::MultiMesh> multimesh)
        : dolfin::MultiMeshFunctionSpace(multimesh) {
        // Create and add standard function spaces
        for (std::size_t part = 0; part < multimesh->num_parts(); part++) {
            std::shared_ptr<const dolfin::FunctionSpace> V(new Form_F_FunctionSpace_0(multimesh->part(part)));
            add(V);
        }

        // Build multimesh function space
        build();
    }
};

typedef CoefficientSpace_u Form_F_FunctionSpace_1;

typedef CoefficientSpace_f Form_F_FunctionSpace_2;

class Form_F : public dolfin::Form {
  public:
    // Constructor
    Form_F(std::shared_ptr<const dolfin::FunctionSpace> V0) : dolfin::Form(1, 2), u(*this, 0), f(*this, 1) {
        _function_spaces[0] = V0;

        _ufc_form = std::make_shared<const nonlinearpoisson_form_0>();
    }

    // Constructor
    Form_F(std::shared_ptr<const dolfin::FunctionSpace> V0, std::shared_ptr<const dolfin::GenericFunction> u,
           std::shared_ptr<const dolfin::GenericFunction> f)
        : dolfin::Form(1, 2), u(*this, 0), f(*this, 1) {
        _function_spaces[0] = V0;

        this->u = u;
        this->f = f;

        _ufc_form = std::make_shared<const nonlinearpoisson_form_0>();
    }

    // Destructor
    ~Form_F() {}

    /// Return the number of the coefficient with this name
    virtual std::size_t coefficient_number(const std::string& name) const {
        if (name == "u")
            return 0;
        else if (name == "f")
            return 1;

        dolfin::dolfin_error("generated code for class Form", "access coefficient data", "Invalid coefficient");
        return 0;
    }

    /// Return the name of the coefficient with this number
    virtual std::string coefficient_name(std::size_t i) const {
        switch (i) {
        case 0:
            return "u";
        case 1:
            return "f";
        }

        dolfin::dolfin_error("generated code for class Form", "access coefficient data", "Invalid coefficient");
        return "unnamed";
    }

    // Typedefs
    typedef Form_F_FunctionSpace_0          TestSpace;
    typedef Form_F_MultiMeshFunctionSpace_0 MultiMeshTestSpace;
    typedef Form_F_FunctionSpace_1          CoefficientSpace_u;
    typedef Form_F_FunctionSpace_2          CoefficientSpace_f;

    // Coefficients
    dolfin::CoefficientAssigner u;
    dolfin::CoefficientAssigner f;
};

class MultiMeshForm_F : public dolfin::MultiMeshForm {
  public:
    // Constructor
    MultiMeshForm_F(std::shared_ptr<const dolfin::MultiMeshFunctionSpace> V0)
        : dolfin::MultiMeshForm(V0), u(*this, 0), f(*this, 1) {
        // Create and add standard forms
        std::size_t num_parts = V0->num_parts(); // assume all equal and pick first
        for (std::size_t part = 0; part < num_parts; part++) {
            std::shared_ptr<dolfin::Form> a(new Form_F(V0->part(part)));
            add(a);
        }
        // Build multimesh form
        build();

        /// Assign coefficients
    }

    // Constructor
    MultiMeshForm_F(std::shared_ptr<const dolfin::MultiMeshFunctionSpace> V0,
                    std::shared_ptr<const dolfin::GenericFunction> u, std::shared_ptr<const dolfin::GenericFunction> f)
        : dolfin::MultiMeshForm(V0), u(*this, 0), f(*this, 1) {
        // Create and add standard forms
        std::size_t num_parts = V0->num_parts(); // assume all equal and pick first
        for (std::size_t part = 0; part < num_parts; part++) {
            std::shared_ptr<dolfin::Form> a(new Form_F(V0->part(part)));
            add(a);
        }
        // Build multimesh form
        build();

        /// Assign coefficients
        this->u = u;
        this->f = f;
    }

    // Destructor
    ~MultiMeshForm_F() {}

    /// Return the number of the coefficient with this name
    virtual std::size_t coefficient_number(const std::string& name) const {
        if (name == "u")
            return 0;
        else if (name == "f")
            return 1;

        dolfin::dolfin_error("generated code for class Form", "access coefficient data", "Invalid coefficient");
        return 0;
    }

    /// Return the name of the coefficient with this number
    virtual std::string coefficient_name(std::size_t i) const {
        switch (i) {
        case 0:
            return "u";
        case 1:
            return "f";
        }

        dolfin::dolfin_error("generated code for class Form", "access coefficient data", "Invalid coefficient");
        return "unnamed";
    }

    // Typedefs
    typedef Form_F_FunctionSpace_0          TestSpace;
    typedef Form_F_MultiMeshFunctionSpace_0 MultiMeshTestSpace;
    typedef Form_F_FunctionSpace_1          CoefficientSpace_u;
    typedef Form_F_FunctionSpace_2          CoefficientSpace_f;

    // Coefficients
    dolfin::MultiMeshCoefficientAssigner u;
    dolfin::MultiMeshCoefficientAssigner f;
};

